  public void Save(){if(Game==null)return;try{Game.State.utc=Game.Now();store.Write(Game.State);}catch(Exception e){Debug.LogError("Could not save restaurant: "+e.Message);Notify("Could not save. Please check free storage.");}}
  AudioClip Tone(string title,float a,float b,float duration){int count=(int)(44100*duration);var data=new float[count];for(int i=0;i<count;i++){float t=i/44100f,f=Mathf.Lerp(a,b,t/duration);data[i]=Mathf.Sin(2*Mathf.PI*f*t)*Mathf.Sin(Mathf.PI*i/count)*.11f;}var clip=AudioClip.Create(title,count,1,44100,false);clip.SetData(data,0);return clip;}
  void Sound(AudioClip clip){if(Game.State.sfx)audioSource.PlayOneShot(clip);}
