  void OfflineDialog(){Dialog("Welcome back", "Your team kept the restaurant going. Offline earnings: "+Economy.Money(Game.State.pendingOffline)+". Your team earns while you are away, for up to a day. There are no paid boosts.","COLLECT",()=>{double value=Game.ClaimOffline();Save();CloseModal();Notify("Collected "+Economy.Money(value));});}
  void TutorialDialog(){if(Game.State.introComplete){Dialog("How to play","Guests order, collect food, sit down and eat. Your team serves them automatically. Buy green upgrades to make your restaurant better. Open restaurants on the map and earn tickets to grow your team.","LET'S PLAY",CloseModal);return;}Dialog("Welcome to your restaurant!","Let's welcome our first guest. Your team will take orders, prepare food and serve it. You choose which upgrades to buy. We'll show you one step at a time.","OPEN MY RESTAURANT",()=>{Game.BeginService();CloseModal();Save();});}
  void Dialog(string title,string message,string action,Action click){if(modal)CloseModal();var shade=Panel("Dialog shade",safe,Vector2.zero,Vector2.one,new Color(.10f,.16f,.13f,.48f));modal=Panel("Dialog",shade,new Vector2(.05f,.24f),new Vector2(.95f,.76f),Cream);Text(modal,title,new Vector2(.06f,.78f),new Vector2(.80f,.97f),33,Ink);Text(modal,message,new Vector2(.07f,.38f),new Vector2(.93f,.78f),28,Ink);Button(modal,action,new Vector2(.08f,.17f),new Vector2(.92f,.33f),click,Green,22);Button(modal,"×",new Vector2(.83f,.84f),new Vector2(.99f,.99f),CloseModal,Peach,23);}

  static Sprite Rounded(){if(round)return round;int size=48;var texture=new Texture2D(size,size,TextureFormat.RGBA32,false);for(int y=0;y<size;y++)for(int x=0;x<size;x++){float dx=Mathf.Max(12-x,x-35),dy=Mathf.Max(12-y,y-35);float distance=Mathf.Sqrt(Mathf.Max(0,dx)*Mathf.Max(0,dx)+Mathf.Max(0,dy)*Mathf.Max(0,dy));texture.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01(12.5f-distance)));}texture.Apply();round=Sprite.Create(texture,new Rect(0,0,size,size),Vector2.one*.5f,100,0,SpriteMeshType.FullRect,new Vector4(16,16,16,16));return round;}
  AudioClip Music(){int rate=22050;float length=16;var data=new float[(int)(rate*length)];int[] notes={60,64,67,71,57,60,64,67,53,57,60,64,55,59,62,67};for(int i=0;i<data.Length;i++){float t=i/(float)rate;int beat=(int)(t*2);float local=t%0.5f,env=Mathf.Exp(-local*8);float hz=440*Mathf.Pow(2,(notes[beat%notes.Length]-69)/12f);data[i]=(.14f*Mathf.Sin(2*Mathf.PI*hz*t)+.04f*Mathf.Sin(2*Mathf.PI*hz*2*t))*env;}var clip=AudioClip.Create("Original cozy marimba loop",data.Length,1,rate,false);clip.SetData(data,0);return clip;}
  void CloseModal(){if(modal)Destroy(modal.parent.gameObject);modal=null;if(Game!=null&&Game.Family&&Game.Guide==0)Game.BeginService();Refresh();}
 }
